<script setup>
import { computed, ref } from 'vue'
import { Download, Search, RotateCcw, ArrowLeft, ArrowRight } from 'lucide-vue-next'
import { useAppStore } from '../stores/app'
import { api } from '../api'
import { money, localDate, statusNames } from '../utils/format'
import PaymentTable from '../components/PaymentTable.vue'
const store=useAppStore(), status=ref(''), employee=ref(''), from=ref(''), until=ref(''), page=ref(1)
const filtered=computed(()=>store.sortedPayments.filter(p=>(!status.value||p.status===status.value)&&(!employee.value||p.employeeId===employee.value)&&(!from.value||localDate(p.createdAt)>=from.value)&&(!until.value||localDate(p.createdAt)<=until.value)))
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/10)))
const currentPage=computed(()=>Math.min(page.value,pages.value))
const visible=computed(()=>filtered.value.slice((currentPage.value-1)*10,currentPage.value*10))
function reset(){status.value='';employee.value='';from.value='';until.value='';page.value=1}
const exportError=ref(''),exporting=ref(false)
async function download(){exporting.value=true;exportError.value='';try{const blob=await api.exportPayments({currency:store.currency,status:status.value,employee_id:employee.value,start:from.value,end:until.value});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='tipro-payments.csv';a.click();URL.revokeObjectURL(url);store.notify('История экспортирована')}catch(e){exportError.value=e.message}finally{exporting.value=false}}

</script>
<template><div class="page-heading"><div><h1>{{ store.session?.role==='employee'?$t('Мои платежи'):$t('Платежи ресторана') }}</h1><p>{{ store.session?.role==='employee'?$t('Здесь отображаются только ваши чаевые.'):$t('Все платежи команды вашего ресторана.') }}</p></div><button class="btn btn-outline" @click="download" :disabled="!filtered.length||exporting"><Download :size="17"/>{{ $t('Экспорт CSV') }}</button></div><p v-if="exportError" class="error-banner" role="alert">{{ $t(exportError) }}</p><section class="panel"><div class="filters"><label>{{ $t('Статус') }}<select v-model="status" @change="page=1"><option value="">{{ $t('Все статусы') }}</option><option value="success">{{ $t('Успешно') }}</option><option value="declined">{{ $t('Отклонён') }}</option><option value="created">{{ $t('Создан') }}</option><option value="pending">{{ $t('Ожидает') }}</option><option value="cancelled">{{ $t('Отменён') }}</option></select></label><label v-if="store.session?.role==='merchant'">{{ $t('Сотрудник') }}<select v-model="employee" @change="page=1"><option value="">{{ $t('Вся команда') }}</option><option v-for="e in store.employees" :value="e.id" :key="e.id">{{ e.name }}</option></select></label><label>{{ $t('С даты') }}<input type="date" v-model="from" :max="until || undefined" @change="page=1"></label><label>{{ $t('По дату') }}<input type="date" v-model="until" :min="from || undefined" @change="page=1"></label><button class="icon-btn" @click="reset" :aria-label="$t('Сбросить фильтры')" :title="$t('Сбросить фильтры')"><RotateCcw :size="18"/></button></div><div class="filter-summary"><span>{{ $t('Найдено платежей:') }} <strong>{{ filtered.length }}</strong></span><span>{{ $t('Успешные чаевые:') }} <strong>{{ money(filtered.filter(p=>p.status==='success').reduce((s,p)=>s+p.amount,0)) }}</strong></span></div><PaymentTable :payments="visible" :employee-name="store.employeeName"/><div class="pagination"><span>{{ $t('Страница') }} {{ currentPage }} {{ $t('из') }} {{ pages }}</span><div><button class="icon-btn" :disabled="currentPage===1" @click="page=currentPage-1" :aria-label="$t('Предыдущая страница')"><ArrowLeft :size="17"/></button><button class="icon-btn" :disabled="currentPage===pages" @click="page=currentPage+1" :aria-label="$t('Следующая страница')"><ArrowRight :size="17"/></button></div></div></section></template>
